UPDATE "Product"
SET
    "title" = '{"id":"Balsem Cap Beruang","en":"Bear Brand Balm"}',
    "merk" = '{"id":"Beruang","en":"Bear"}',
    "detail" = '{"id":"Garansi Barang 100% Asli.\r\n\r\nProduksi;\r\nPT. Granindo - Makassar Indonesia.\r\n\r\nBalsem gosok dan urut multiguna\r\nAsli oleh-oleh MAKASAR, yang sudah terkenal, dengan banyak Khasiat untuk kesehatan.\r\nAman dan tanpa Efek samping.\r\nTerbuat dari rempah-rempah alami warisan yang sudah turun temurun selama 10 generasi.\r\n\r\nkhasiat dan kegunaan antara lain;\r\n1. untuk Pijat dan Urut pegal, masuk angin, dll.\r\n2. Luka bakar, Gatal-gatal, Lecet dll.\r\n3. Gigitan Serangga.\r\n4. Deman, muntah, dll\r\njuga di gunakan sebagai aroma terapi dan\r\nAman untuk pemakaian sehari dan Aman pemakaian waktu lama.","en":"100% Authentic Product Guarantee.\n\nProduced by: PT. Granindo - Makassar Indonesia.\n\nMulti-purpose rubbing and massaging balm. Authentic souvenir from MAKASSAR, widely known for its various health benefits. Safe without side effects. Made from natural inherited herbs passed down for 10 generations.\n\nIndications and uses:\n1. For massage, muscle aches, catching a cold, etc.\n2. Burns, itching, scrapes, etc.\n3. Insect bites.\n4. Fever, vomiting, etc.\nAlso used as aromatherapy. Safe for daily use and long-term application."}'
WHERE "productId" = 39
   OR "title" = 'Balsem Cap Beruang'
   OR (json_valid("title") AND json_extract("title", '$.id') = 'Balsem Cap Beruang');

UPDATE "Product"
SET
    "title" = '{"id":"Balsem Cap Tawon","en":"Wasp Brand Balm"}',
    "merk" = '{"id":"Tawon","en":"Wasp"}',
    "detail" = '{"id":"Garansi Barang 100%Asli.\r\nProduksi PT. Tawon Jaya Makassar.\r\n\r\nBalsem gosok dan urut multiguna\r\nAsli oleh-oleh MAKASAR, yang sudah terkenal, dengan banyak Khasiat untuk kesehatan.\r\nAman dan tanpa Efek samping.\r\nTerbuat dari rempah-rempah alami warisan yang sudah turun temurun.\r\n\r\nkhasiat dan kegunaan antara lain;\r\n1. untuk Pijat dan mengatasi berbagai macam masalah atau keluhan nyeri otot dan sendi.\r\n2. Luka bakar, Gatal-gatal, Lecet dll.\r\n3. Gigitan Serangga.\r\n4. bisa digunakan untuk menghangatkan badan saat masuk angin atau kurang sehat.\r\ncukup oleskan pada punggung, leher dan perut\r\n\r\nAman untuk pemakaian sehari dan Aman pemakaian waktu lama.","en":"100% Authentic Product Guarantee.\nProduced by: PT. Tawon Jaya Makassar.\n\nMulti-purpose rubbing and massaging balm. Authentic souvenir from MAKASSAR, widely known for its various health benefits. Safe without side effects. Made from natural inherited herbs.\n\nIndications and uses:\n1. For massage and overcoming various muscle and joint pain complaints.\n2. Burns, itching, scrapes, etc.\n3. Insect bites.\n4. Can be used to warm the body when catching a cold or feeling unwell; simply apply to the back, neck, and stomach.\n\nSafe for daily use and long-term application."}'
WHERE "productId" = 40
   OR "title" = 'Balsem Cap Tawon'
   OR (json_valid("title") AND json_extract("title", '$.id') = 'Balsem Cap Tawon');

UPDATE "Product"
SET
    "title" = '{"id":"Minyak Cap Tawon Reguler","en":"Wasp Brand Medicated Oil Regular"}',
    "merk" = '{"id":"Tawon","en":"Wasp"}',
    "detail" = '{"id":"Garansi Barang 100%Asli.\r\nProduksi PT. Tawon Jaya Makassar.\r\ndengan Ciri keaslian;\r\n1. Tutup ada gambar Tawon yang timbul. ( logo ini ada pada semua tutup produk Tawon Jaya yg ASLI).\r\n2. Ada Segel, segel Plastik berlogo tawon\r\n4.Label Produk ada pengaman Hologram\r\n\r\nMinyak gosok dan urut multiguna\r\nAsli oleh-oleh MAKASAR, yang sudah terkenal, dengan banyak Khasiat untuk kesehatan.\r\nAman dan tanpa Efek samping.\r\nTerbuat dari rempah-rempah alami warisan yang sudah turun temurun.\r\n\r\nkhasiat dan kegunaan antara lain;\r\n1. untuk Pijat dan mengatasi berbagai macam masalah atau keluhan nyeri otot dan sendi.\r\n2. Luka bakar, Gatal-gatal, Lecet dll.\r\n3. Gigitan Serangga.\r\n4. bisa digunakan untuk menghangatkan badan saat masuk angin atau kurang sehat.\r\ncukup oleskan pada punggung, leher dan perut\r\n\r\nAman untuk pemakaian sehari dan Aman pemakaian waktu lama.","en":"100% Authentic Product Guarantee.\nProduced by: PT. Tawon Jaya Makassar.\nAuthenticity marks:\n1. The cap features an embossed Wasp image (this logo is on all authentic Tawon Jaya caps).\n2. Features a plastic seal with the wasp logo.\n4. Product label includes a security hologram.\n\nMulti-purpose rubbing and massaging oil. Authentic souvenir from MAKASSAR, widely known for its various health benefits. Safe without side effects. Made from natural inherited herbs.\n\nIndications and uses:\n1. For massage and overcoming various muscle and joint pain complaints.\n2. Burns, itching, scrapes, etc.\n3. Insect bites.\n4. Can be used to warm the body when catching a cold or feeling unwell; simply apply to the back, neck, and stomach.\n\nSafe for daily use and long-term application."}'
WHERE "productId" = 41
   OR "title" = 'Minyak Cap Tawon Reguler'
