UPDATE "Product"
SET
    "title" = '{"id":"Minyak Kayu Balitung","en":"Balitung Wood Oil"}',
    "merk" = '{"id":"-","en":"-"}',
    "detail" = '{"id":"Minyak kayu balitung anti uban 100% asli Kalimantan\r\n\r\nMinyak ini berbahan dasar sari kayu balitung yang hanya ada di pedalaman kalimantan, yang mampu menghitamkan rambut anda dari pangkal hingga ujung. MKB difermentasikan menjadi minyak yang prosesnya membutuhkan waktu 1 bulan, bahkan tidak hanya disitu saja minyak yang sudah jadi akan diendapkan agar mendapat hasil sempurna dan murni, karena proses tsb produksi minyak ini tidak terlalu banyak, jika anda melihat produk sejenis di pasarkan secara bebas hati-hati mungkin palsu, karna warga sekitar tidak menjual belikan produk ini ke sembarang orang apalagi memproduksinya dalam jumlah banyak.\r\n\r\nBagaiman ramuan Minyak Kayu Balitung OBAT UBAN bekerja?\r\n\r\nMKB bekerja dengan alami sedikit demi sedikit tapi menuju sifat permanen, bukan bersifat instan, tidak langsung seperti anda menwarnai/mencat rambut tiba-tiba kinclong namun akhirnya kelak uban akan tumbuh lagi.\r\n\r\nMKB merangsang sel-sel kulit kepala untuk menumbuhkan rambut baru dan merontokan rambut yang tidak sehat, jadi anda dapat mendapatkan hasil rambut hitam dan indah yang permanen.\r\n\r\nProses penghitaman pada akar rambut bertahap dan hasilnya akan terlihat ketika rambut baru akan tumbuh, rambut tersebut akan menjadi hitam\r\n\r\nKhasiat Ramuan Minyak Kayu Balitung OBAT UBAN:\r\n\r\nMenghitamkan rambut yang sudah putih dan yang memerah\r\nMenumbuhkan rambut yang sudah rontok / botak\r\nMenebalkan rambut yang mulai menipis\r\n\r\nCara Pakai Minyak Kayu Balitung OBAT UBAN :\r\n\r\nKocok terlebih dahulu sebelum dioleskan.\r\nOleskan secukupnya pada kulit kepala hingga rata sebelum tidur malam hari\r\nPagi bisa di bilas dengan air , jangan gunakan shampoo\r\nPakai setiap malam, setiap hari\r\nKeramas dengan shampoo 2 hari sekali waktu sore\r\n\r\nTanpa Efek Samping\r\n\r\nAWAS.. OBAT LUAR, BUKAN UNTUK DIMINUM..!!!","en":"100% Authentic Balitung Wood Anti-Gray Hair Oil from Kalimantan.\n\nMade from Balitung wood sap found only deep inside the forests of Kalimantan, capable of darkening your hair from root to tip. It is fermented into oil over a 1-month process, then settled for perfect murni output. Because of this lengthy production process, quantities are limited. Be cautious of cheap imitations.\n\nHow does it work?\nIt works naturally and gradually towards permanent results, rather than an instant hair dye trick that fades away later. It stimulates scalp cells to grow healthy new dark hair and sheds unhealthy strands.\n\nBenefits:\n- Darkens graying or reddening hair\n- Regrows hair on thinning or balding spots\n- Thickens thinning hair\n\nDirections:\nShake well before use. Apply adequately over the scalp before bed. Rinse with water in the morning (do not use shampoo). Apply every night. Wash with shampoo once every 2 days in the afternoon.\nNo side effects.\nWARNING: FOR EXTERNAL USE ONLY, DO NOT SWALLOW!"}'
WHERE "productId" = 47
   OR "title" = 'Minyak Kayu Balitung'
   OR (json_valid("title") AND json_extract("title", '$.id') = 'Minyak Kayu Balitung');

UPDATE "Product"
SET
    "title" = '{"id":"Minyak Kayu Putih Cap Beruang Grizzly","en":"Grizzly Bear Brand Cajuput Oil"}',
    "merk" = '{"id":"Beruang Grizzly","en":"Bear Grizzly"}',
    "detail" = '{"id":"Minyak Kayuputih cap Beruang Grizzly\r\n\r\nKomposisi Minyak Kayu Putih Asli ( Cajeput Oil)\r\n\r\nDeskripsi Produk :\r\n\r\nKhasiat dan Kegunaan :\r\nMembantu meredakan sakit perut, kembung, masuk angin, mual, digigit serangga dan gatal gatal\r\n\r\nCara Pakai :\r\nOleskan pada permukaan kulit atau bagian yang sakit, kemudian digosok / urut\r\n\r\nKomposisi :\r\nMinyak Kayu Putih Asli\r\n\r\nDiproduksi Oleh :\r\nPT.Granindo\r\nMakassar - Indonesia\r\nPOM TR 183 617 121","en":"Bear Grizzly Cajuput Oil.\n\nComposition: Authentic Cajuput Oil.\n\nBenefits and Indications:\nHelps relieve stomach ache, bloating, symptoms of catching a cold, nausea, insect bites, and minor itching.\n\nDirections:\nApply onto the skin surface or affected areas, then rub or massage gently.\n\nProduced by: PT. Granindo, Makassar - Indonesia. POM TR 183 617 121"}'
WHERE "productId" = 48
   OR "title" = 'Minyak Kayu Putih Cap Beruang Grizzly'
   OR (json_valid("title") AND json_extract("title", '$.id') = 'Minyak Kayu Putih Cap Beruang Grizzly');

UPDATE "Product"
SET
    "title" = '{"id":"Minyak Kayu Putih Cap Kuda Bangau Reguler","en":"Kuda Bangau Cajuput Oil Regular"}',
    "merk" = '{"id":"Kuda Bangau","en":"Kuda Bangau"}',
    "detail" = '{"id":"Produk Minyak Kayu Putih cap Kuda Bangau Reguler.\r\n\r\nSegel Kuning ada logo Kuda Bangau.\r\n\r\nMinyak Kayu Putih ASLI dari tempat penyulingannya di Ambon Asli Namlea.\r\nSeperti diketahui Pulau buru sangat terkenal dengan minyak kayu putihnya dan sudah diakui bahwa kualitas daun kayu putih pulau buru adalah yang paling bagus dan aromanya sangat wangi.\r\nKita bisa menemukan berbagai pohon kayu putih di seluruh wilayah Buru Namlea.\r\n\r\nKOMPOSISI:\r\n-Setiap botol Mengandung Minyak Kayu Putih 100% (Oleum Cajuputih)\r\n\r\nKHASIAT :\r\n- Membantu Menghangatkan bandan.\r\n- Membantu meredakan gatal-gatal akibat digigit serangga.\r\n- Membantu meredakan gejala masuk angin seperti perut kembung dan mual.\r\n\r\nCARA PEMAKAIAN :\r\n- Digosok pada bagian yang sakit atau yang memerlukan rasa hangat.\r\n\r\nCARA PENYIMPANAN :\r\n- Simpan ditempat sejuk dan kering.\r\n\r\nPERHATIAN:\r\nObat luar.","en":"Kuda Bangau Cajuput Oil Regular Product.\n\nYellow Seal featuring the Kuda Bangau logo.\n\nAUTHENTIC Cajuput oil directly sourced from its distillation center in Namlea, Ambon. Buru Island is highly acclaimed for its cajuput oil, recognized for having the highest quality leaves and a very fragrant aroma.\n\nComposition: Each bottle contains 100% Cajuput Oil (Oleum Cajuputi).\n\nBenefits:\n- Helps warm up the body.\n- Helps soothe itching from insect bites.\n- Helps relieve signs of catching a cold, such as bloating and nausea.\n\nDirections: Rub onto painful areas or parts needing warmth.\nStorage: Keep in a cool, dry place.\nWarning: External medicine."}'
WHERE "productId" = 49
   OR "title" = 'Minyak Kayu Putih Cap Kuda Bangau Reguler'
   OR (json_valid("title") AND json_extract("title", '$.id') = 'Minyak Kayu Putih Cap Kuda Bangau Reguler');

UPDATE "Product"
SET
    "title" = '{"id":"Minyak Kayu Putih Cap Kuda Bangau Super","en":"Kuda Bangau Cajuput Oil Super"}',
    "merk" = '{"id":"Kuda Bangau","en":"Kuda Bangau"}',
    "detail" = '{"id":"Produk Minyak Kayu Putih cap Kuda Bangau Super.\r\n\r\nSegel Merah ada logo Kuda Bangau.\r\n\r\nPerbedaan Super dan Reguler adalah dari Tingkat Kemurnian Penyulingan,\r\nSuper lebih harum dan Tidak Terasa Lengket\r\n\r\nMinyak Kayu Putih ASLI dari tempat penyulingannya di Ambon Asli Namlea.\r\nSeperti diketahui Pulau buru sangat terkenal dengan minyak kayu putihnya dan sudah diakui bahwa kualitas daun kayu putih pulau buru adalah yang paling bagus dan aromanya sangat wangi.\r\nKita bisa menemukan berbagai pohon kayu putih di seluruh wilayah Buru Namlea.\r\n\r\nKOMPOSISI:\r\n-Setiap botol Mengandung Minyak Kayu Putih 100% (Oleum Cajuputih)\r\n\r\nKHASIAT :\r\n- Membantu Menghangatkan bandan.\r\n- Membantu meredakan gatal-gatal akibat digigit serangga.\r\n- Membantu meredakan gejala masuk angin seperti perut kembung dan mual.\r\n\r\nCARA PEMAKAIAN :\r\n- Digosok pada bagian yang sakit atau yang memerlukan rasa hangat.\r\n\r\nCARA PENYIMPANAN :\r\n- Simpan ditempat sejuk dan kering.\r\n\r\nPERHATIAN:\r\nObat luar.","en":"Kuda Bangau Cajuput Oil Super Product.\n\nRed Seal featuring the Kuda Bangau logo.\n\nThe difference between Super and Regular lies in the purity level of the distillation process; Super is more fragrant and does not feel sticky on the skin.\n\nAUTHENTIC Cajuput oil directly sourced from its distillation center in Namlea, Ambon. Buru Island is highly acclaimed for its cajuput oil, recognized for having the highest quality leaves and a very fragrant aroma.\n\nComposition: Each bottle contains 100% Cajuput Oil (Oleum Cajuputi).\n\nBenefits:\n- Helps warm up the body.\n- Helps soothe itching from insect bites.\n- Helps relieve signs of catching a cold, such as bloating and nausea.\n\nDirections: Rub onto painful areas or parts needing warmth.\nStorage: Keep in a cool, dry place.\nWarning: External medicine."}'
WHERE "productId" = 50
   OR "title" = 'Minyak Kayu Putih Cap Kuda Bangau Super'
