   OR (json_valid("slug") AND json_extract("slug", '$.en') = 'norway-thrashed-by-france-erling-haaland-better-rest-on-balcony-rubbing-bear-brand-roll-on');

UPDATE "News"
SET
    "slug" = '{"id":"mohamed-salah-cedera-hamstring-tim-medis-mesir-siapkan-senjata-rahasia-minyak-cap-tawon","en":"mohamed-salah-hamstring-injury-egyptian-medical-team-prepares-secret-weapon-tawon-oil"}',
    "title" = '{"id":"Mohamed Salah Cedera Hamstring, Tim Medis Mesir Siapkan Senjata Rahasia \"Minyak Cap Tawon\"","en":"Mohamed Salah Hamstring Injury, Egyptian Medical Team Prepares Secret Weapon \"Tawon Oil\""}',
    "summary" = '{"id":"Kabar mengejutkan datang dari ruang ganti Timnas Mesir usai laga dramatis melawan Iran di babak grup Piala Dunia 2026. Sang megabintang, Mohamed Salah, terpaksa ditarik keluar akibat cedera hamstring.","en":"Shocking news comes from the Egypt National Team dressing room after a dramatic match against Iran in the 2026 World Cup group stage."}',
    "contentHtml" = '{"id":"<p><strong>JAKARTA</strong> – Kabar mengejutkan datang dari ruang ganti Timnas Mesir usai laga dramatis melawan Iran di babak grup Piala Dunia 2026. Sang megabintang, Mohamed Salah, terpaksa ditarik keluar pada menit ke-56 setelah otot hamstring-nya dilaporkan \"meronta-ronta\" minta pensiun dini. Kejadian ini sukses membuat seluruh warga Mesir senam jantung berjamaah jelang laga krusial babak 32 besar melawan Australia.</p><p>Ketika tim medis Liverpool mulai panik dan menyiapkan jet pribadi untuk menerbangkan Salah ke pusat rehabilitasi tercanggih di Eropa, pelatih Hossam Hassan justru terlihat santai sambil menyeruput kopi.</p><p>Usut punya usut, tim medis Mesir ternyata punya secret weapon kearifan lokal yang siap mengangkangi semua teknologi medis modern: <a href=\"/product/42\">Minyak Cap Tawon Super</a>.</p><h2>Khasiat Magis Minyak Tawon vs Cedera Hamstring</h2><p>Menurut sumber internal yang tidak mau disebutkan namanya (karena takut disengat tawon asli), tim medis Mesir kabarnya telah mengamankan pasokan satu kontainer Minyak Tawon langsung dari Makassar. Minyak legendaris beraroma khas ini diyakini menjadi kunci kesembuhan instan sang firaun Liverpool.</p><p><img src=\"https://res.cloudinary.com/djk2qql9w/image/upload/v1782631881/2_k4bx9y.jpg\" alt=\"Mohamed Salah Minyak Tawon\" /></p><p>\"Hamstring robek? Otot ketarik? Ah, itu cuma karena Salah kurang diurut pakai Minyak Tawon gosok hangat. Begitu dioles, jangankan lari mengejar bola, mengejar takdir pun Salah pasti sanggup,\" ujar seorang cenayang sepak bola yang optimis.</p><p>Bahkan muncul rumor di media sosial bahwa aroma Minyak Tawon yang semerbak di ruang ganti Mesir berhasil membuat bek-bek Australia gemetar duluan sebelum bertanding. Mereka mengira Mesir sedang menyiapkan ritual sihir kuno, padahal itu cuma bau aromaterapi anti-masuk angin.</p><h2>Respons Santai Hossam Hassan</h2><p>Dalam konferensi persnya, pelatih Hossam Hassan menegaskan bahwa rakyat Mesir tidak perlu cemas berlebihan.</p><p>\"Saya sudah bicara dengan Salah. Kondisinya aman. Dia cuma butuh dibalur Minyak Tawon seluruh badan, lalu dibungkus selimut tebal sampai keringatan. Insya Allah, besok pas lawan Australia dia sudah bisa main, bahkan sambil kayang kalau perlu,\" gurau Hassan dengan penuh percaya diri.</p><p>Hassan juga menambahkan bahwa jika taktik Minyak Tawon ini berhasil, ia berencana mengganti seluruh sponsor suplemen medis Timnas Mesir dengan produk-produk legendaris lainnya, seperti koyo cabai dan balsem otot berpictogram macan.</p><h2>Badai Cedera? Bukan Masalah!</h2><p>Mesir memang sedang apes karena kehilangan setengah skuadnya akibat cedera dan akumulasi kartu. Mohamed Abdelmonem cedera lutut, Ahmed Fatouh tertatih-tatih di lapangan, dan Mohanad Lashin kena skorsing. Namun, dengan hadirnya <a href=\"/product/42\">Minyak Cap Tawon Super</a> di kotak P3K mereka, semua masalah medis tersebut mendadak terasa seperti komedo yang mudah dihempas.</p><p>Kita tunggu saja apakah kilatan minyak di paha Mohamed Salah akan membawa Mesir terbang tinggi ke babak 16 besar, atau justru membuat lapangan pertandingan di Seattle berbau seperti minyak urut panti jompo. Tetap optimis, Ya Masr!</p>","en":"<p><strong>JAKARTA</strong> - Shocking news came from Egypt''s dressing room after a dramatic match against Iran in the 2026 World Cup group stage. Mohamed Salah had to leave the pitch in the 56th minute because of a hamstring problem.</p><p>The injury made Egyptian supporters nervous before the important round of 32 match against Australia. While modern medical teams prepared serious recovery plans, fans joked that Egypt still had one traditional secret weapon: <a href=\"/product/42\">Tawon Oil Super</a>.</p><h2>Tawon Oil vs Hamstring Drama</h2><p>In this playful football story, Egypt''s medical team had prepared a supply of legendary oil from Makassar. Its strong aroma and warm sensation were imagined as the key to helping Salah recover.</p><p><img src=\"https://res.cloudinary.com/djk2qql9w/image/upload/v1782631881/2_k4bx9y.jpg\" alt=\"Mohamed Salah Tawon Oil\" /></p><p>Fans joked that if the oil was applied properly, Salah would not only run after the ball, but also chase destiny itself.</p><h2>Hossam Hassan Stays Calm</h2><p>Coach Hossam Hassan was described as calm and confident. In a funny version of the press conference, he told fans not to worry too much because Salah only needed warmth, rest, and a good rubdown.</p><p>The joke spread quickly because many Indonesian families know the habit of using warm oil when the body feels sore or tired.</p><h2>Injury Storm? Not a Problem</h2><p>Egypt had several player problems, including injuries and suspensions. But with <a href=\"/product/42\">Tawon Oil Super</a> in the first-aid box, the story becomes lighter and funnier.</p><p>Will Salah return quickly and help Egypt fly into the next round? Nobody knows. But one thing is clear: in football comedy, hope sometimes smells like traditional rubbing oil.</p>"}'
WHERE "newsId" = 3
   OR "slug" = 'mohamed-salah-cedera-hamstring-tim-medis-mesir-siapkan-senjata-rahasia-minyak-cap-tawon'
